"""Write reports/INDEX.md: every report in the corpus, by format then emitter.

Usage: python3 scripts/index.py [REPORTS_DIR]
"""

import json
import os
import sys


def render(manifests):
    rows = []
    for m in manifests:
        for r in m["reports"]:
            size = r.get("bytes", sum(f["bytes"] for f in r.get("files", {}).values()))
            rows.append((r["format"], m["emitter"], r["path"], size))
    rows.sort()
    out = [
        "# Report corpus index",
        "",
        "Generated by `scripts/index.py` from each emitter's `manifest.json`. Do not edit by hand.",
        "",
        "## Emitters",
        "",
        "| Emitter | Image | Tools |",
        "|---|---|---|",
    ]
    for m in sorted(manifests, key=lambda m: m["emitter"]):
        tools = "; ".join(f"{k}: `{v}`" for k, v in sorted(m["tools"].items()))
        out.append(f"| [{m['emitter']}]({m['emitter']}/manifest.json) | `{m['image']}` | {tools} |")
    out += ["", "## Reports", "", "| Format | Emitter | Report | Bytes |", "|---|---|---|---|"]
    for fmt, emitter, path, size in rows:
        out.append(f"| {fmt} | {emitter} | [{path}]({emitter}/{path}) | {size:,} |")
    return "\n".join(out) + "\n"


def main(argv):
    reports = argv[1] if len(argv) > 1 else os.path.join(os.path.dirname(__file__), "..", "reports")
    manifests = []
    for e in sorted(os.listdir(reports)):
        p = os.path.join(reports, e, "manifest.json")
        if os.path.isfile(p):
            with open(p) as f:
                manifests.append(json.load(f))
    with open(os.path.join(reports, "INDEX.md"), "w") as f:
        f.write(render(manifests))


if __name__ == "__main__":
    main(sys.argv)
